package tarea14;
import javax.swing.JOptionPane;
public class boletin02_08_b_doWhile {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
    			int i = 100;
    			do {
					JOptionPane.showMessageDialog(null, i);
					i = i - 7;
				} while (i >= 0);
    			

	}

}
